/**
 * Free for Dev catalog — domain library.
 *
 * A read-only directory of free-tier developer services (SaaS, PaaS, IaaS and
 * friends) curated from the community-maintained free-for.dev list
 * (https://free-for.dev/, source repo github.com/ripienaar/free-for-dev).
 * `data.json` is generated by `scripts/sync-free-for-dev.mjs` and carries the
 * upstream provenance (commit + sync date) in `source`.
 *
 * Browser- and server-safe pure module: no `node:*`, Prisma, or auth imports,
 * so both the dashboard UI and API routes can share the same query helpers.
 */
import dataJson from "./data.json";
import jixserverJson from "./jixserver.json";

export interface FreeForDevService {
  id: string;
  name: string;
  /** Provider URL. Almost always https; a few endpoints use other schemes (stun:). */
  url: string;
  /** One-line free-tier summary, in the list's own words. */
  summary: string;
  /** Extra free-tier detail bullets (limits, caveats, sub-products). */
  details: string[];
}

export interface FreeForDevCategory {
  id: string;
  label: string;
  /** Anchor on free-for.dev, kept so links back to the source resolve. */
  anchor: string;
  services: FreeForDevService[];
}

export interface FreeForDevSource {
  name: string;
  listUrl: string;
  repoUrl: string;
  /** Upstream commit the data was synced from, or null when not recorded. */
  commit: string | null;
  /** ISO date (YYYY-MM-DD) of the last sync. */
  syncedAt: string;
  attribution: string;
  historical?: boolean;
}

interface FreeForDevData {
  source: FreeForDevSource;
  categories: FreeForDevCategory[];
}

const data: FreeForDevData = dataJson;
const jixserver: FreeForDevData = {
  source: jixserverJson.source,
  categories: jixserverJson.categories.map((category) => ({
    ...category,
    services: category.services.map((service) => ({ ...service, summary: "", details: [] })),
  })),
};
export type CatalogId = "community" | "jixserver";
export function catalogSource(id: CatalogId = "community") { return (id === "jixserver" ? jixserver : data).source; }
function categoriesFor(id: CatalogId = "community"): readonly FreeForDevCategory[] {
  return id === "jixserver" ? jixserver.categories : data.categories;
}

export const FREE_FOR_DEV_SOURCE: FreeForDevSource = data.source;
export const FREE_FOR_DEV_CATEGORIES: readonly FreeForDevCategory[] = Object.freeze(data.categories);

export interface CategorySummary {
  id: string;
  label: string;
  anchor: string;
  count: number;
}

export interface CategorizedService extends FreeForDevService {
  categoryId: string;
  categoryLabel: string;
}

export interface FreeServiceQuery {
  /** Restrict to one category id (see `listCategories`). */
  categoryId?: string;
  source?: CatalogId;
  /** Case-insensitive match against name, summary and detail text. */
  q?: string;
  /** Maximum number of services to return (matched total is still reported). */
  limit?: number;
}

export interface FreeServiceQueryResult {
  categories: CategorySummary[];
  /** Number of services matching the filters, before `limit` is applied. */
  total: number;
  services: CategorizedService[];
}

export function listCategories(source?: CatalogId): CategorySummary[] {
  return categoriesFor(source).map((c) => ({
    id: c.id,
    label: c.label,
    anchor: c.anchor,
    count: c.services.length,
  }));
}

export function getCategory(id: string, source?: CatalogId): FreeForDevCategory | null {
  return categoriesFor(source).find((c) => c.id === id) ?? null;
}

export function getService(id: string): CategorizedService | null {
  for (const category of FREE_FOR_DEV_CATEGORIES) {
    const service = category.services.find((s) => s.id === id);
    if (service) {
      return { ...service, categoryId: category.id, categoryLabel: category.label };
    }
  }
  return null;
}

export function countServices(): number {
  return FREE_FOR_DEV_CATEGORIES.reduce((n, c) => n + c.services.length, 0);
}

function matchesQuery(service: FreeForDevService, needle: string): boolean {
  const haystack = `${service.name}\n${service.summary}\n${service.details.join("\n")}`.toLowerCase();
  return haystack.includes(needle);
}

/**
 * Query the catalog. Pure: the same filters always return the same rows.
 * Services keep their upstream order within each category.
 */
export function queryFreeServices(query: FreeServiceQuery = {}): FreeServiceQueryResult {
  const categories = listCategories(query.source);
  const needle = (query.q ?? "").trim().toLowerCase();

  const matched: CategorizedService[] = [];
  for (const category of categoriesFor(query.source)) {
    if (query.categoryId && category.id !== query.categoryId) continue;
    for (const service of category.services) {
      if (needle && !matchesQuery(service, needle)) continue;
      matched.push({ ...service, categoryId: category.id, categoryLabel: category.label });
    }
  }

  const total = matched.length;
  const services = typeof query.limit === "number" ? matched.slice(0, query.limit) : matched;
  return { categories, total, services };
}
